  if (['Pending', 'Draft', 'Returned'].includes(e.status) && ed) A.push(`<button class="btn" data-act="rmEntryForm" data-k="${e.id}">Verify &amp; edit</button>`, `<button class="btn primary" data-act="rmSubmit" data-k="${e.id}">Submit for verification</button>`);
  if (e.status === 'Approved' && can('rm_entries', 'Post') && (regular || can('rm_entries', 'Approve') || App.user.role === 'CFO')) A.push(`<button class="btn primary" data-act="rmPost" data-k="${e.id}">Process &amp; post</button>`);
  if (e.status === 'Approved' && can('rm_entries', 'Post') && !(regular || can('rm_entries', 'Approve') || App.user.role === 'CFO')) A.push('<span class="small muted">Exceptional entry – posting by Finance Manager / CFO</span>');
  if (['Posted', 'Partly paid'].includes(e.status) && can('rm_ledger', 'Post')) A.push(`<button class="btn primary" data-act="rmPayForm" data-k="${e.id}">Record payment</button>`);
