PAGES.rm_reports = { title: 'Rent Reports', mod: 'rm_reports', group: true, render() {
  const key = RM_REPORTS.some(r => r[0] === App.ui.rmRep) ? App.ui.rmRep : 'branch', def = RM_REPORTS.find(r => r[0] === key); let R; try { R = def[2](); } catch (e) { console.error(e); return `<div class="note bad">${esc(e.message)}</div>`; }
  const f = App.ui.rmRF || {}; let rows = R.rows; if (f.ll) rows = rows.filter(r => { const name = r.landlord ? (typeof r.landlord === 'string' ? r.landlord : r.landlord.name) : (rmMaster(r.master) || { landlord: {} }).landlord.name; return !name || name === f.ll; }); if (f.from || f.to) rows = rows.filter(r => { const d = r.dueDate || r.expiry || (r.postedAt || r.at || '').slice(0, 10); return !d || ((!f.from || d >= f.from) && (!f.to || d <= f.to)); });
  const NOSUM = /days|rate|%|growth|variance %/i, totalVals = rows.length ? R.cols.map(c => ['inr', 'num'].includes(c.t) && !NOSUM.test(c.h) ? rows.reduce((s, r) => { let x; try { x = c.x ? c.x(r) : c.k(r); } catch (e) { x = 0; } return s + (typeof x === 'number' && isFinite(x) ? x : 0); }, 0) : null) : null;
  const lls = [...new Set(RT().masters.map(m => m.landlord.name))].sort();
  return `<div class="srf-strip2"><label class="fld"><span>Report</span><select data-act="uiSel" data-k="rmRep">${RM_REPORTS.map(([k, l]) => `<option value="${k}" ${k === key ? 'selected' : ''}>${esc(l)}</option>`).join('')}</select></label>${rmBrSel()}<label class="fld"><span>Landlord</span><select data-act="rmRF" data-k="ll"><option value="">All</option>${lls.map(l => `<option ${f.ll === l ? 'selected' : ''}>${esc(l)}</option>`).join('')}</select></label><label class="fld"><span>From</span><input type="date" data-act="rmRF" data-k="from" value="${f.from || ''}"></label><label class="fld"><span>To</span><input type="date" data-act="rmRF" data-k="to" value="${f.to || ''}"></label><span class="grow"></span><span class="small">${rows.length} rows</span></div>${card(def[1], table('rmRep', R.cols, rows, { totalVals, compact: true, title: def[1], limit: 150, empty: 'No records for this report and the selected filters.' }), { right: exportBtns('rmRep', 'rm_reports') })}`;
} };
