PAGES.rm_admin = { title: 'Rent Control Centre', mod: 'rm_admin', render() {
  const M = RMM(), c = M.cfg, tab = pcTab('ra', 'rules'), ed = can('rm_admin', 'Edit'), num = (id, val) => `<input id="${id}" type="number" min="0" value="${val}" ${ed ? '' : 'disabled'}>`;
  const tabs = pcTabs('ra', [['rules', 'Workflow, limits & alerts'], ['gl', 'GL accounts'], ['tds', 'TDS sections'], ['types', 'Rent types'], ['budget', 'Rent budgets']], 'rules');
  let body;
  if (tab === 'gl') body = `${ed ? '<div class="btnrow"><input id="gl_code" placeholder="Code" style="width:90px"><input id="gl_name" placeholder="Account name"><select id="gl_type"><option>Expense</option><option>Asset</option><option>Liability</option><option>Bank</option></select><button class="btn sm primary" data-act="rmGlAdd">Add account</button></div>' : ''}` + table('rmGl', [{ h: 'Code', k: g => g.code, t: 'text' }, { h: 'Account', k: g => g.name, t: 'text' }, { h: 'Type', k: g => g.type, t: 'text' }, { h: 'Used in', k: g => (({ '1401': 'Input GST (CGST) on posting', '1402': 'Input GST (SGST) on posting', '1403': 'Input IGST', '2101': 'Credited on posting, debited by TDS and payment', '2201': 'Credited with TDS on posting', '1501': 'Security deposit entries', '1502': 'Advance rent entries' })[g.code] || (g.type === 'Bank' ? 'Credited on payment' : g.type === 'Expense' ? 'Debited on posting (mapped per master / kind)' : '')), t: 'text', cls: 'small' }, { h: 'Balance (Dr +)', k: g => rmGlBalance(g.code), t: 'inr' }, { h: 'Status', k: g => rmStatusPill(g.active ? 'Active' : 'Inactive'), t: 'html', x: g => g.active ? 'Active' : 'Inactive' }], M.gl, { compact: true, title: 'Rent chart of accounts' }) + `<div class="form-grid" style="margin-top:10px">${pcFld('Default bank for payments', pcSel('g_bank', M.gl.filter(g => g.type === 'Bank').map(g => [g.code, `${g.code} ${g.name}`]), c.defaultBank))}${pcFld('GST posting', pcSel('g_split', [['1', 'Split CGST / SGST (intra-state)'], ['0', 'IGST (inter-state)']], c.gstSplit ? '1' : '0'))}</div>${ed ? '<button class="btn primary" data-act="rmCfgSave" data-k="gl">Save</button>' : ''}`;
  else if (tab === 'tds') body = `${ed ? '<div class="btnrow"><input id="td_sec" placeholder="Section" style="width:100px"><input id="td_desc" placeholder="Description"><input id="td_pct" type="number" step="0.5" placeholder="%" style="width:80px"><input id="td_thr" type="number" placeholder="Threshold ₹" style="width:130px"><button class="btn sm primary" data-act="rmTdsAdd">Add / update</button></div>' : ''}` + table('rmTds', [{ h: 'Section', k: t => t.sec, t: 'text' }, { h: 'Nature', k: t => t.desc, t: 'text' }, { h: 'Rate %', k: t => t.pct, t: 'num' }, { h: 'Annual threshold', k: t => t.threshold, t: 'inr' }, { h: 'Masters using', k: t => RT().masters.filter(m => m.tds.applicable && m.tds.section === t.sec).length, t: 'num' }], M.tds, { compact: true, title: 'TDS sections and rates' });
  else if (tab === 'types') body = `${ed ? '<div class="btnrow"><input id="ty_name" placeholder="Rent type"><button class="btn sm primary" data-act="rmTypeAdd">Add type</button></div>' : ''}` + table('rmTypes', [{ h: 'Rent type', k: t => t, t: 'text' }, { h: 'Masters', k: t => RT().masters.filter(m => m.rentType === t).length, t: 'num' }, { h: 'Monthly rent', k: t => RT().masters.filter(m => m.rentType === t && m.status === 'Active').reduce((s, m) => s + m.amount, 0), t: 'inr' }], M.types, { compact: true, title: 'Rent types' });
  else if (tab === 'budget') { const rows = Object.keys(M.budgets).map(k => ({ k, bid: k === 'CORP' ? '' : k, b: M.budgets[k] })).filter(r => r.bid ? (RM_CORP() || pcScopeBr().has(r.bid)) : RM_CORP()); body = `<div class="btnrow">${ed ? '<button class="btn sm primary" data-act="rmBudgetForm">Set budget</button>' : ''}</div>` + table('rmBud', [{ h: 'Branch', k: r => rmBr(r.bid), t: 'text' }, { h: 'Annual rent budget', k: r => r.b.budget, t: 'inr' }, { h: 'Monthly', k: r => Math.round(r.b.budget / 12), t: 'inr' }, { h: 'Previous year actual', k: r => r.b.prevYear, t: 'inr' }, { h: 'Agreement value (annual)', k: r => RT().masters.filter(m => (m.bid || 'CORP') === r.k && m.status === 'Active').reduce((s, m) => s + rmRentFor(m, PROC_TODAY.slice(0, 7)).amount * 12, 0), t: 'inr' }], rows, { compact: true, title: 'Rent budgets by branch', limit: 100 }); }
  else body = `<h4 class="blk">Workflow and limits</h4><div class="form-grid">${pcFld('Finance Manager verification required on every entry', pcSel('r_ver', [['1', 'Yes'], ['0', 'No – regular rent posts after Accounts verification']], c.verifyRequired ? '1' : '0'))}${pcFld('CFO approval for net payment above (₹)', num('r_cfo', c.cfoAbove))}${pcFld('Direct posting by Accounts for regular rent up to (₹)', num('r_direct', c.directPostMax))}${pcFld('Default GST % for new masters', num('r_gst', c.gstPct))}${pcFld('Default notice period (days)', num('r_notice', c.noticeDefault))}${pcFld('Requester may verify own entry', pcSel('r_self', [['0', 'No'], ['1', 'Yes']], c.allowSelf ? '1' : '0'))}${pcFld('System Admin may act on any level', pcSel('r_adm', [['1', 'Yes'], ['0', 'No']], c.adminOverride ? '1' : '0'))}</div><h4 class="blk">Alerts</h4><div class="form-grid">${pcFld('Due-date alerts (days before, comma separated; 0 = on due date)', `<input id="r_alert" value="${esc(c.alertDays.join(', '))}" ${ed ? '' : 'disabled'}>`)}${pcFld('Agreement renewal alert (days before expiry)', num('r_ren', c.renewalAlertDays))}${pcFld('Email notifications', pcSel('r_mail', [['1', 'On (simulated)'], ['0', 'In-app only']], c.notifyEmail ? '1' : '0'))}</div><h4 class="blk">Period lock and number series</h4><div class="form-grid">${pcFld('Locked periods (YYYY-MM, comma separated)', `<input id="r_lock" value="${esc((c.lockedPeriods || []).join(', '))}" ${ed ? '' : 'disabled'}>`)}${Object.entries(c.numbering).map(([k, p]) => pcFld({ RM: 'Rent master', RE: 'Rent entry', JV: 'Journal voucher', PY: 'Payment' }[k] || k, `<input id="n_${k}" value="${esc(p)}" maxlength="6" ${ed ? '' : 'disabled'}>`)).join('')}</div>${ed ? '<button class="btn primary" data-act="rmCfgSave" data-k="rules">Save rules</button>' : ''}<p class="small muted" style="margin-top:8px">Draft: Accounts Executive / Branch Accountant / Finance Executive · Verification: Finance Manager / Corporate Finance · Final approval and payment above the limit: CFO. Posted entries cannot be deleted – only reversed by Finance Manager / CFO with a reason.</p>`;
  return card('Rent Control Centre', tabs + body, { sub: 'Every change is recorded in the audit trail with the reason.' });
} };
Object.assign(RM_ACT, {
  rmGlAdd: () => { const code = (v('gl_code') || '').trim(), name = (v('gl_name') || '').trim(), type = v('gl_type'); if (!/^\d{4}$/.test(code) || !name) return toast('Enter a 4-digit code and name.', 'bad'); askReason('Add GL account', `${code} ${name}`, async r => { const M = Store.clone(RMM()); if (M.gl.some(g => g.code === code)) return toast('Code in use.', 'bad'); M.gl.push({ code, name, type, active: true }); await Store.put('rent', M); audit('Rent Management', 'GL account added', { new: `${code} ${name} (${type})`, reason: r }); }); },
  rmTdsAdd: () => { const sec = (v('td_sec') || '').trim(), desc = (v('td_desc') || '').trim(), pct = +v('td_pct'), thr = +v('td_thr') || 0; if (!sec || !(pct >= 0)) return toast('Enter the section and rate.', 'bad'); askReason('Save TDS section', `${sec} @ ${pct}%`, async r => { const M = Store.clone(RMM()); const ex = M.tds.find(t => t.sec === sec); if (ex) Object.assign(ex, { desc: desc || ex.desc, pct, threshold: thr }); else M.tds.push({ sec, desc, pct, threshold: thr }); await Store.put('rent', M); audit('Rent Management', 'TDS section saved', { new: `${sec} · ${pct}% · threshold ${INR(thr)}`, reason: r }); }); },
  rmTypeAdd: () => { const name = (v('ty_name') || '').trim(); if (!name) return toast('Enter the rent type.', 'bad'); askReason('Add rent type', name, async r => { const M = Store.clone(RMM()); if (!M.types.includes(name)) M.types.push(name); await Store.put('rent', M); audit('Rent Management', 'Rent type added', { new: name, reason: r }); }); },
  rmBudgetForm: () => { const brs = DATA.branches.filter(b => !b.closed && (RM_CORP() || pcScopeBr().has(b.id))).map(b => [b.id, b.name]); if (RM_CORP()) brs.unshift(['CORP', 'Corporate Office']); modal('Set rent budget', `<div class="form-grid">${pcFld('Branch', pcSel('rb_bid', brs, pcMyBranch() || 'CORP'))}${pcFld('Annual rent budget (₹)', '<input id="rb_amt" type="number" min="0" step="1000">')}${pcFld('Previous year actual (₹)', '<input id="rb_prev" type="number" min="0" step="1000">')}</div>`, `<button class="btn" data-act="closeModal">Cancel</button><button class="btn primary" data-act="rmBudgetOk">Save</button>`); },
  rmBudgetOk: () => { const k = v('rb_bid'), amt = +v('rb_amt') || 0, prev = +v('rb_prev') || 0; askReason('Set rent budget', `${k === 'CORP' ? 'Corporate Office' : brName(k)} · ${INR(amt)}`, async r => { const M = Store.clone(RMM()); const old = M.budgets[k] || { budget: 0, prevYear: 0 }; M.budgets[k] = { budget: amt, prevYear: prev || old.prevYear }; await Store.put('rent', M); audit('Rent Management', 'Rent budget set', { old: INR(old.budget), new: `${k} · ${INR(amt)}`, reason: r }); }); },
  rmCfgSave: t => { if (!document.getElementById(t.dataset.k === 'gl' ? 'g_bank' : 'r_cfo')) return toast('Open the settings tab first.', 'bad'); const M = Store.clone(RMM()), c = M.cfg, old = JSON.stringify(c); if (t.dataset.k === 'gl') { c.defaultBank = v('g_bank'); c.gstSplit = v('g_split') === '1'; } else { Object.assign(c, { verifyRequired: v('r_ver') === '1', cfoAbove: +v('r_cfo') || 0, directPostMax: +v('r_direct') || 0, gstPct: +v('r_gst') || 18, noticeDefault: +v('r_notice') || 90, allowSelf: v('r_self') === '1', adminOverride: v('r_adm') === '1', alertDays: (v('r_alert') || '7,3,0').split(',').map(x => +x.trim()).filter(x => x >= 0), renewalAlertDays: +v('r_ren') || 90, notifyEmail: v('r_mail') === '1', lockedPeriods: (v('r_lock') || '').split(',').map(x => x.trim()).filter(x => /^\d{4}-\d{2}$/.test(x)) }); Object.keys(c.numbering).forEach(k => c.numbering[k] = (v('n_' + k) || k).trim().toUpperCase()); } askReason('Save rent settings', 'Applies to new entries; entries already in verification keep their route.', async r => { await Store.put('rent', M); audit('Rent Management', 'Settings changed', { old: old.slice(0, 400), new: JSON.stringify(M.cfg).slice(0, 400), reason: r }); toast('Settings saved.'); }); }
});
